"""Reproduce the 189 independent AA HL mathematical checks without writing files.

Run from any directory:
    python /path/to/repository/scripts/ib-2026-authoring/aa_hl_independent.py
Or from the repository root:
    python scripts/ib-2026-authoring/aa_hl_independent.py

Requires ordinary SymPy and SciPy installations (or a caller-supplied PYTHONPATH).
Historical prose/visual review notes are retained as evidence; executing this
script reproduces the symbolic and numerical checks, not a fresh visual review.
The question batch and saved independent-review JSON are never modified.
"""
import json,math,hashlib,sys,itertools
from pathlib import Path
ROOT = Path(__file__).resolve().parents[2]
BATCH_PATH = ROOT / "content/ib/math-2026-expansion/aa-hl.json"
import sympy as s
from scipy.stats import norm,binom
from scipy.integrate import quad
q=json.loads(BATCH_PATH.read_text(encoding='utf8'));by={v['id']:v for v in q};records=[]
x,t,k,n=s.symbols('x t k n',real=True);I=s.I

def C(label,actual,expected,tol=1e-9):
 if isinstance(actual,s.MatrixBase):
  assert actual.equals(expected),(label,actual,expected)
  return {'check':label,'actual':str(actual),'expected':str(expected),'residual':str(actual-expected)}
 if isinstance(actual,(s.Basic,)) or isinstance(expected,(s.Basic,)):
  z=s.simplify(actual-expected)
  if z!=0: assert abs(complex(z.evalf()))<tol,(label,z)
  return {'check':label,'actual':str(s.simplify(actual)),'expected':str(expected),'residual':str(z)}
 assert abs(actual-expected)<=tol*max(1,abs(expected)),(label,actual,expected)
 return {'check':label,'actual':actual,'expected':expected,'absoluteError':abs(actual-expected)}
